import {test} from 'node:test';
import assert from 'node:assert/strict';
import {withRetry} from '../src/retry.mjs';

test('hidden check', async () => {
  let attempts = 0;
  assert.equal(await withRetry(async () => { if (attempts++ < 2) throw Object.assign(Error('busy'), {status: 503}); return 'ok'; }, {sleep: async () => {}}), 'ok');
  assert.equal(attempts, 3);
  attempts = 0;
  await assert.rejects(withRetry(async () => { attempts++; throw Object.assign(Error('bad'), {status: 500}); }, {sleep: async () => {}}), /bad/);
  assert.equal(attempts, 1);
});
